package com.maeen.mahfilhub.ui.viewmodel

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.maeen.mahfilhub.data.model.LoginResponse
import com.maeen.mahfilhub.data.repository.AuthRepository
import com.maeen.mahfilhub.data.repository.Resource
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

data class LoginUiState(
    val isLoading: Boolean = false,
    val loginResponse: LoginResponse? = null,
    val errorMessage: String? = null
)

class LoginViewModel(
    private val repository: AuthRepository = AuthRepository()
) : ViewModel() {

    private val _uiState = MutableStateFlow(LoginUiState())
    val uiState: StateFlow<LoginUiState> = _uiState.asStateFlow()

    fun login(email: String, password: String) {
        // Basic client-side validation
        if (email.isBlank()) {
            _uiState.value = LoginUiState(errorMessage = "Please enter your email")
            return
        }
        if (password.isBlank()) {
            _uiState.value = LoginUiState(errorMessage = "Please enter your password")
            return
        }

        viewModelScope.launch {
            _uiState.value = LoginUiState(isLoading = true)
            when (val result = repository.login(email, password)) {
                is Resource.Success -> {
                    _uiState.value = LoginUiState(loginResponse = result.data)
                }
                is Resource.Error -> {
                    _uiState.value = LoginUiState(errorMessage = result.message)
                }
                is Resource.Loading -> {
                    // Already handled above
                }
            }
        }
    }

    fun clearError() {
        _uiState.value = _uiState.value.copy(errorMessage = null)
    }

    fun resetState() {
        _uiState.value = LoginUiState()
    }
}

package com.maeen.mahfilhub.util
import android.content.Context import android.content.SharedPreferences
/** * Simple session manager backed by SharedPreferences. * Stores login state and basic user info. * Replace static values with real API data later. */ object SessionManager {
private const val PREF_NAME = "mahfilhub_session" private const val KEY_IS_LOGGED_IN = "is_logged_in" private const val KEY_USER_NAME = "user_name" private const val KEY_USER_EMAIL = "user_email"
private fun prefs(context: Context): SharedPreferences = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
// ── Login state ─────────────────────────────────────────────────────
fun isLoggedIn(context: Context): Boolean = prefs(context).getBoolean(KEY_IS_LOGGED_IN, false)
/** * Save login session. Uses static placeholder values for now. * Replace with real API response data later. */ fun login(context: Context, name: String = "Guest User", email: String = "user@mahfilhub.com") { prefs(context).edit() .putBoolean(KEY_IS_LOGGED_IN, true) .putString(KEY_USER_NAME, name) .putString(KEY_USER_EMAIL, email) .apply() }
fun logout(context: Context) { prefs(context).edit() .putBoolean(KEY_IS_LOGGED_IN, false) .remove(KEY_USER_NAME) .remove(KEY_USER_EMAIL) .apply() }
// ── User info ───────────────────────────────────────────────────────
fun getUserName(context: Context): String = prefs(context).getString(KEY_USER_NAME, "Guest") ?: "Guest"
fun getUserEmail(context: Context): String = prefs(context).getString(KEY_USER_EMAIL, "") ?: ""
}

package com.maeen.mahfilhub.util
import android.content.Context import android.content.SharedPreferences
/** * Simple session manager backed by SharedPreferences. * Stores login state, token, role and basic user info. */ object SessionManager {
private const val PREF_NAME = "mahfilhub_session" private const val KEY_IS_LOGGED_IN = "is_logged_in" private const val KEY_USER_NAME = "user_name" private const val KEY_USER_EMAIL = "user_email" private const val KEY_AUTH_TOKEN = "auth_token" private const val KEY_USER_ROLE = "user_role"
private fun prefs(context: Context): SharedPreferences = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
// ── Login state ─────────────────────────────────────────────────────
fun isLoggedIn(context: Context): Boolean = prefs(context).getBoolean(KEY_IS_LOGGED_IN, false)
/** * Save login session with token and role from API response. */ fun login( context: Context, token: String, role: String, email: String = "" ) { prefs(context).edit() .putBoolean(KEY_IS_LOGGED_IN, true) .putString(KEY_AUTH_TOKEN, token) .putString(KEY_USER_ROLE, role) .putString(KEY_USER_EMAIL, email) .apply() }
/** * Save login session for guest mode (no token). */ fun loginAsGuest(context: Context) { prefs(context).edit() .putBoolean(KEY_IS_LOGGED_IN, true) .putString(KEY_USER_NAME, "Guest User") .putString(KEY_USER_EMAIL, "guest@mahfilhub.com") .putString(KEY_USER_ROLE, "GUEST") .apply() }
fun logout(context: Context) { prefs(context).edit().clear().apply() }
// ── Token ───────────────────────────────────────────────────────────
fun getToken(context: Context): String? = prefs(context).getString(KEY_AUTH_TOKEN, null)
fun getRole(context: Context): String = prefs(context).getString(KEY_USER_ROLE, "") ?: ""
// ── User info ───────────────────────────────────────────────────────
fun getUserName(context: Context): String = prefs(context).getString(KEY_USER_NAME, "Guest") ?: "Guest"
fun getUserEmail(context: Context): String = prefs(context).getString(KEY_USER_EMAIL, "") ?: "" }

